import { useNavigate } from "react-router-dom";
import { useState } from "react";
import "../App.css";
import { uploadSwiggyCSV, startSwiggyScraping, getSwiggyJobStatus, downloadSwiggyResults, retrySwiggyFailedUrls } from "../services/api";
import ProgressTracker from "./ProgressTracker";
import StartScraperModal from "./StartScraperModal";

function SwiggyUpload() {
  const navigate = useNavigate();
  const [file, setFile] = useState(null);
  const [jobId, setJobId] = useState(null);
  const [resIds, setResIds] = useState([]);
  const [showModal, setShowModal] = useState(false);
  const [isScrapingStarted, setIsScrapingStarted] = useState(false);
  const [jobStatus, setJobStatus] = useState(null);
  const [error, setError] = useState(null);

  const handleFileChange = async (e) => {
    const selectedFile = e.target.files[0];
    setFile(selectedFile);
    setError(null);

    if (selectedFile) {
      try {
        const result = await uploadSwiggyCSV(selectedFile);
        setJobId(result.job_id);
        setResIds(result.res_ids);
        setShowModal(true);
      } catch (err) {
        setError("Failed to upload file. Please check the format.");
        console.error(err);
      }
    }
  };

  const handleStartScraping = async () => {
    try {
      setShowModal(false);
      await startSwiggyScraping(jobId, resIds);
      setIsScrapingStarted(true);

      pollJobStatus();
    } catch (err) {
      setError("Failed to start scraping");
      console.error(err);
    }
  };

  const pollJobStatus = async () => {
    const interval = setInterval(async () => {
      try {
        const result = await getSwiggyJobStatus(jobId);
        setJobStatus(result.job);

        if (result.job.status === "completed") {
          clearInterval(interval);
        }
      } catch (err) {
        console.error("Polling error:", err);
      }
    }, 2000);
  };

  const handleDownload = async () => {
    try {
      await downloadSwiggyResults(jobId);
    } catch (err) {
      setError("Failed to download results");
      console.error(err);
    }
  };

  const handleRetryFailed = async () => {
    try {
      await retrySwiggyFailedUrls(jobId);
      setIsScrapingStarted(true);
      pollJobStatus();
    } catch (err) {
      setError("Failed to retry");
      console.error(err);
    }
  };

  return (
    <div className="container">
      <button className="back-btn" onClick={() => navigate("/")}>
        ← Back to Dashboard
      </button>

      <div className="platform-header">
        <div className="platform-icon">🍔</div>
        <div>
          <h1 className="platform-title">Swiggy Scraper</h1>
          <p className="platform-subtitle">Upload CSV file with restaurant IDs</p>
        </div>
      </div>

      {error && (
        <div className="error-banner">
          <span>⚠️ {error}</span>
        </div>
      )}

      {!isScrapingStarted ? (
        <div className="upload-section">
          <div className="upload-card">
            <div className="upload-header">
              <h3>📄 Upload CSV File</h3>
              <p>File must contain a column named "res_id"</p>
            </div>

            <div className="upload-body">
              <label className="file-input-label">
                <input
                  type="file"
                  accept=".csv"
                  onChange={handleFileChange}
                  className="file-input"
                />
                <div className="file-input-button">
                  <span className="upload-icon">📁</span>
                  <span>Choose CSV File</span>
                </div>
              </label>

              {file && (
                <div className="file-info">
                  <span className="file-icon">✓</span>
                  <div>
                    <div className="file-name">{file.name}</div>
                    <div className="file-size">
                      {(file.size / 1024).toFixed(2)} KB
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="csv-format">
              <h4>Expected CSV Format:</h4>
              <pre>
{`res_id
787978
766
9304`}
              </pre>
            </div>
          </div>
        </div>
      ) : (
        <ProgressTracker
          jobStatus={jobStatus}
          onDownload={handleDownload}
          onRetry={handleRetryFailed}
        />
      )}

      <StartScraperModal
        show={showModal}
        onClose={() => setShowModal(false)}
        onStart={handleStartScraping}
        totalUrls={resIds.length}
      />
    </div>
  );
}

export default SwiggyUpload;
